func (c *Config) KubeProxyHostPort() (string, int) {
	if c.KubeProxyAddr != "" {
		addr, err := utils.ParseAddr(c.KubeProxyAddr)
		if err == nil {
			host := addr.Host()
			if ip := net.ParseIP(host); ip != nil && ip.IsUnspecified() {
