+func (s *ConfigTestSuite) TestKubernetesProxyListenerWarning(c *check.C) {
+	logger := log.StandardLogger()
+	previousOutput := logger.Out
+	previousLevel := log.GetLevel()
+	defer log.SetOutput(previousOutput)
+	defer log.SetLevel(previousLevel)
+	log.SetLevel(log.WarnLevel)
+
+	tests := []struct {
+		name            string
+		kubeEnabled     string
+		kubeServiceAddr string
+		proxyEnabled    string
+		legacyEnabled   string
+		kubeListenAddr  string
+		shouldWarn      bool
+	}{
+		{"both services enabled without a listener", "yes", "", "yes", "", "", true},
+		{"Kubernetes service configured by listener", "", "0.0.0.0:3026", "yes", "", "", true},
+		{"shorthand Kubernetes proxy enabled", "yes", "", "yes", "", "0.0.0.0:8080", false},
+		{"legacy Kubernetes proxy enabled", "yes", "", "yes", "yes", "", false},
+		{"Kubernetes service disabled", "no", "", "yes", "", "", false},
+		{"proxy service disabled", "yes", "", "no", "", "", false},
+	}
+	for _, tt := range tests {
+		var output bytes.Buffer
+		log.SetOutput(&output)
+		fc := &FileConfig{}
+		fc.Kube.EnabledFlag = tt.kubeEnabled
+		fc.Kube.ListenAddress = tt.kubeServiceAddr
+		fc.Proxy.EnabledFlag = tt.proxyEnabled
+		fc.Proxy.Kube.EnabledFlag = tt.legacyEnabled
+		fc.Proxy.KubeListenAddr = tt.kubeListenAddr
+		cfg := service.MakeDefaultConfig()
+		err := ApplyFileConfig(fc, cfg)
+		c.Assert(err, check.IsNil, check.Commentf("%s", tt.name))
+		warned := strings.Contains(output.String(), "proxy_service has no Kubernetes listener")
+		c.Assert(warned, check.Equals, tt.shouldWarn, check.Commentf("%s", tt.name))
+	}
+}

